const Default = () => <Footer
    navLinks={[
      { href: '/', label: 'Home' },
      { href: '/about', label: 'About' },
      { href: '/services', label: 'Services' },
      { href: '/contact', label: 'Contact' },
    ]}
    contactInfo={{
      email: 'hello@example.com',
      phone: '+1 (555) 123-4567',
      address: '123 Main Street, City, State 12345',
    }}
    socialLinks={[
      { href: 'https://github.com', icon: <Github className="h-5 w-5" />, label: 'GitHub' },
      { href: 'https://twitter.com', icon: <Twitter className="h-5 w-5" />, label: 'Twitter' },
      { href: 'https://linkedin.com', icon: <Linkedin className="h-5 w-5" />, label: 'LinkedIn' },
    ]} />;

const NavigationOnly = () => <Footer
    navLinks={[
      { href: '/', label: 'Home' },
      { href: '/about', label: 'About' },
      { href: '/services', label: 'Services' },
    ]} />;

const SocialOnly = () => <Footer
    socialLinks={[
      { href: 'https://github.com', icon: <Github className="h-5 w-5" />, label: 'GitHub' },
      { href: 'https://twitter.com', icon: <Twitter className="h-5 w-5" />, label: 'Twitter' },
    ]} />;

const WithCustomCopyright = () => <Footer
    navLinks={[
      { href: '/', label: 'Home' },
      { href: '/about', label: 'About' },
    ]}
    copyright="© 2026 Custom Company. All rights reserved." />;

const WithCustomLogo = () => <Footer
    logo={<div className="text-xl font-bold">YDM</div>}
    navLinks={[
      { href: '/', label: 'Home' },
      { href: '/services', label: 'Services' },
    ]} />;

const WithCustomLogo = () => <Header
    navItems={[
      { href: '/', label: 'Home' },
      { href: '/about', label: 'About' },
    ]}
    logo={<div className="text-2xl font-bold text-primary">YDM</div>} />;

const AllVariants = () => (
  <div className="flex flex-wrap gap-4">
    <Button variant="default">Default</Button>
    <Button variant="destructive">Destructive</Button>
    <Button variant="outline">Outline</Button>
    <Button variant="secondary">Secondary</Button>
    <Button variant="ghost">Ghost</Button>
    <Button variant="link">Link</Button>
  </div>
);

const AllSizes = () => (
  <div className="flex items-center gap-4">
    <Button size="sm">Small</Button>
    <Button size="default">Default</Button>
    <Button size="lg">Large</Button>
    <Button size="icon">🔔</Button>
  </div>
);

const WithoutHeader = () => (
  <Card className="w-[350px]">
    <CardContent>
      <p>This card has no header, just content.</p>
    </CardContent>
    <CardFooter>
      <Button>Action</Button>
    </CardFooter>
  </Card>
);

const ContentOnly = () => (
  <Card className="w-[350px]">
    <CardContent>
      <p>This card has only content, no header or footer.</p>
    </CardContent>
  </Card>
);

